select UNITE_ID uniteId, PRT_BAG_ID prtBagId, IND_ID indId, START_DATE startDate, END_DATE endDate, FINPROD_ID finprodId, WARN_COND warnCond, APPROVE_COND approveCond, FOUL_COND foulCond from RSK_INDIVID_SPECIAL_STAGE_VIEW
UNITE_TYPE=#{uniteType}
