select m.PARA_CODE,m.PARA_GRANULARITY,m.PARA_DISPLAY_TYPE,m.CONTENT from RSK_ISUP_INDICATOR_PARA_DTL m inner join RSK_ISUP_INDICATOR_PARA n on m.PARA_CODE=n.PARA_CODE
and m.PARA_CODE in ${paramCode}
and m.PARA_GRANULARITY = #{supFrequency}
union all
select m.PARA_CODE,'FIX' as PARA_GRANULARITY,'FIX' AS PARA_DISPLAY_TYPE,m.CONTENT from RSK_ISUP_FIX_RECODE m inner join (select MAX(RSK_ISUP_FIX_RECODE.VALID_DATE) as VALID_DATE,PARA_CODE from RSK_ISUP_FIX_RECODE where RSK_ISUP_FIX_RECODE.VALID_DATE<=to_date('${valDate}','yyyy-MM-dd') group by PARA_CODE) n on m.PARA_CODE=n.PARA_CODE and m.VALID_DATE=n.VALID_DATE inner join RSK_ISUP_INDICATOR_PARA y on m.PARA_CODE=y.PARA_CODE

