mapper.insert:
insert into RSK_ISUP_POINT_DET_VAL (PORTFOLIO_ID , IND_ID , SUP_DATE , SUP_FREQUENCY , ASSET_CODE , ASSET_NAME , SUP_VAL , SUP_STAT , MATH_PROCESS , CREATE_USER , CREATE_DEPT , CREATE_TIME , UPDATE_USER , UPDATE_TIME ) select t1.portfolioId, t1.indId, t1.supDate, t1.supFrequency, t1.assetCode, t1.assetName, t1.supVal, t1.supStat, t1.mathProcess, t1.createUser, t1.createDept, t1.createTime, t1.updateUser, t1.updateTime from (
select #{item.portfolioId, jdbcType=VARCHAR} portfolioId , #{item.indId, jdbcType=INTEGER} indId , #{item.supDate, jdbcType=DATE} supDate , #{item.supFrequency, jdbcType=VARCHAR} supFrequency , #{item.assetCode, jdbcType=VARCHAR} assetCode , #{item.assetName, jdbcType=VARCHAR} assetName , #{item.supVal, jdbcType=VARCHAR} supVal , #{item.supStat, jdbcType=VARCHAR} supStat , #{item.mathProcess, jdbcType=VARCHAR} mathProcess , #{item.createUser, jdbcType=VARCHAR} createUser , #{item.createDept, jdbcType=VARCHAR} createDept , #{item.createTime, jdbcType=TIMESTAMP} createTime , #{item.updateUser, jdbcType=VARCHAR} updateUser , #{item.updateTime, jdbcType=TIMESTAMP} updateTime from dual
) t1

mapper.select:
SELECT DISTINCT prod.prodId "finprodId",max(tt.VAL_DATE) "valDate"
FROM (


				select '${prodId}' as prodId from DUAL



					#{item}



	) prod
LEFT JOIN FIN_PRODUCT fp1
ON fp1.FINPROD_ID = prod.prodId
LEFT JOIN PTL_SEC_VALUTION psv
ON fp1.FINPROD_MARKET_ID = psv.PORTFOLIO_ID
AND psv.CDATE+1= #{dateMax,jdbcType=DATE}
LEFT JOIN FIN_PRODUCT fp
ON fp.FINPROD_ID = psv.FINPROD_ID
AND fp.FINPROD_TYPE2='F17'
LEFT JOIN (
	SELECT PTL_ID,max(VAL_DATE) VAL_DATE from(
		SELECT PORTFOLIO_ID PTL_ID,
			min(VIDT.VALDATE) VAL_DATE
		FROM VALTBL_IMPORT_DATE_TRACE VIDT
		WHERE
			VIDT.VALDATE>=#{dateMin,jdbcType=DATE}
			AND VIDT.VALDATE < #{dateMax,jdbcType=DATE}
			AND VIDT.IMPDATE = #{dateMax,jdbcType=DATE}

				AND	VIDT.CREATE_DEPT = #{deptCode,jdbcType=VARCHAR}

		GROUP BY PORTFOLIO_ID
	)GROUP BY PTL_ID
)tt
ON tt.PTL_ID = fp.FINPROD_MARKET_ID
GROUP BY  prod.prodId
